/**
 * The binary draw-command encoding round-trips to the JSON form.
 *
 * `fixtures/draw-wire.json` is generated by the Rust encoder
 * (`core-libs/petal-ui/src/draw_wire.rs`, test `fixture_is_current`): one
 * sample of every petal-ui `DrawCommand`, as the wire numbers and strings and
 * as serde's JSON. Decoding the one must give the other, so the TypeScript
 * decoder and the Rust encoder cannot drift apart unnoticed.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { decodeDrawCommands } from "../../integrations/petal-web-canvas/src/draw-wire.js";

const fixture = JSON.parse(
  readFileSync(join(__dirname, "fixtures/draw-wire.json"), "utf8"),
) as { numbers: number[]; strings: string[]; commands: any[] };

/** f32 fields reach the buffer widened to f64 (0.1f32 → 0.10000000149…),
 * while serde prints them shortest-f32 (0.1). Compare numbers at f32
 * precision; everything else exactly. */
function close(actual: unknown, expected: unknown, path: string): void {
  if (typeof expected === "number") {
    expect(typeof actual, path).toBe("number");
    expect(Math.fround(actual as number), path).toBe(Math.fround(expected));
  } else if (Array.isArray(expected)) {
    expect(Array.isArray(actual), path).toBe(true);
    expect((actual as unknown[]).length, path).toBe(expected.length);
    expected.forEach((e, i) => close((actual as unknown[])[i], e, `${path}[${i}]`));
  } else if (expected && typeof expected === "object") {
    expect(Object.keys(actual as object).sort(), path).toEqual(Object.keys(expected).sort());
    for (const [k, v] of Object.entries(expected)) close((actual as any)[k], v, `${path}.${k}`);
  } else {
    expect(actual, path).toBe(expected);
  }
}

describe("draw wire decoding", () => {
  it("decodes every command to its JSON form", () => {
    const decoded = decodeDrawCommands(new Float64Array(fixture.numbers), fixture.strings);
    expect(decoded.length).toBe(fixture.commands.length);
    decoded.forEach((cmd, i) => close(cmd, fixture.commands[i], `commands[${i}] (${fixture.commands[i].op})`));
  });

  it("rejects an unknown opcode", () => {
    expect(() => decodeDrawCommands([999], [])).toThrow(/unknown opcode 999/);
  });
});
